import React, { useState } from 'react';
import {useStateMachine} from "little-state-machine";
import {useNavigate} from 'react-router-dom';
import './theme.css';
import './SurveyCitySelectPage.css';
import {DEFAULT_LANG, locale_text} from "./lang";
import {generateSurveyID} from '../core/generateSurvey';

const SubmitButton = (opts) => (
    <button className="button-generic button-stick-to-right button-survey-select-submit" {...opts}></button>
);

const RadioForm = ({lang}) => {
    const navigate = useNavigate();
    const {actions} = useStateMachine();

    const [selected, setSelected] = useState("");
    const [startTime] = useState(new Date());


    const handleSubmit = (e) => {
        e.preventDefault();
        const endTime = new Date();

        // Save answer and timing in state for export/analytics
        const answerKey = `cityselect/yesno`;
        const durationKey = `cityselect/duration`;
        const startTimeKey = `cityselect/start_time`;
        const endTimeKey = `cityselect/end_time`;

        actions.simpleUpdate({
            [answerKey]: selected,
            [durationKey]: endTime - startTime,
            [startTimeKey]: startTime,
            [endTimeKey]: endTime,
        });

        if (selected === "no") {
            navigate("/thankyou");
        } else if (selected === "yes") {
            // Use a default surveyID (e.g., for Seoul)
            // If you have a specific city hash or logic, set here.
            const surveyID = "seoul_" + Math.random().toString(36).substring(2, 10);
            navigate(`/survey/${surveyID}`);
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            <div className="survey-city-select-grid-container">
                <div className="div-option-item">
                    <input
                        type="radio"
                        id="yes"
                        value="yes"
                        checked={selected === "yes"}
                        onChange={() => setSelected("yes")}
                    />
                    <label htmlFor="yes">
                        {locale_text(lang, "survey-city-select-option-yes")}
                    </label>
                </div>
                <div className="div-option-item">
                    <input
                        type="radio"
                        id="no"
                        value="no"
                        checked={selected === "no"}
                        onChange={() => setSelected("no")}
                    />
                    <label htmlFor="no">
                        {locale_text(lang, "survey-city-select-option-no")}
                    </label>
                </div>
            </div>
            <SubmitButton disabled={!selected}>
                {locale_text(lang, 'survey-img-choice-submit-button')}
            </SubmitButton>
        </form>
    );
};

export function SurveyCitySelectPage() {
    const { actions } = useStateMachine();
    console.log('actions:', actions);


    const {state} = useStateMachine();
    const lang = state['language'] || DEFAULT_LANG;

    return (
        <div className="container-page-mid-root">
            <h1 className="title-text city-select-title-text-h1">
                {locale_text(lang, 'survey-city-select-title')}
            </h1>
            <div className="container-after-one-digit">
                <RadioForm lang={lang}/>
            </div>
        </div>
    );
}
